LESSONS=(
Lesson(150,'Lesson_150-declaring-the-grain-before-the-columns','Declaring the grain before the columns','38-declaring-the-grain-before-the-columns.md','wiki.data-modeling.declaring-grain','Phát biểu grain phải mô tả điều gì, kiểm bằng dữ liệu ra sao, và vì sao uniqueness test không tự chứng minh ngữ nghĩa của một row?',(K,H,S),(KL,HL,SL),(
('Grain là hợp đồng ngữ nghĩa','Grain trả lời một row đại diện chính xác cho business event, entity state hay periodic observation nào. Câu phải có đơn vị, phạm vi và thời gian: một order line khi đặt, một account ở cuối ngày, hay một lần chuyển trạng thái. Tên bảng và primary key chỉ là dấu hiệu kỹ thuật; chúng không thay tuyên bố ngữ nghĩa được business owner xác nhận.'),
('Ba grain gần nhau nhưng khác','Order, order line và order-line status event tạo ba số dòng, key và measures khác nhau. Trộn order header amount vào line grain gây nhân tiền; ép status history vào một current-state row làm mất lịch sử. Grain mịn hỗ trợ drill-down nhưng tăng volume; grain tổng hợp giảm chi tiết và không thể phục hồi dimensions đã bỏ.'),
('Kiểm bằng dữ liệu','Lập candidate business key từ grain, chạy group-by/having count lớn hơn một, kiểm null, time range và source duplicates. Duplicate bác bỏ key/grain hiện tại nhưng zero duplicate chưa chứng minh đúng: sample có thể chưa chứa ca biên. Cần profiling theo toàn kỳ, requirement interview và test cases như split shipment, return, correction.'),
('Grain khác key','Grain là ý nghĩa; key là cách nhận dạng row ở grain đó. Nhiều physical keys có thể thực thi cùng grain, và surrogate key unique vẫn không chặn hai rows cùng business grain. Vì vậy lưu/enforce business key hoặc temporal uniqueness phù hợp; document exceptions có lý do thay vì nuốt bằng DISTINCT.'),
('Join đổi grain','One-to-many join có thể nhân rows và measures; many-to-many bridge cần allocation hoặc impact semantics. Trước join ghi input grains, output grain và cardinality assertion. Sau join kiểm row count, distinct business keys, control totals và unmatched rates. Aggregate trước hoặc sau join chỉ hợp lệ nếu phép biến đổi bảo toàn measure ở grain mục tiêu.'),
),('một order khác một order line về row count và measures','status event grain cần event sequence hoặc timestamp đủ phân biệt','snapshot grain phải nêu kỳ và timezone/cutoff','candidate key không null nhưng vẫn có thể sai nghĩa','zero duplicates trên sample không chứng minh uniqueness dài hạn','surrogate primary key có thể che duplicate business grain','DISTINCT che join explosion nhưng không sửa model','header amount lặp trên line grain gây double count','many-to-many join cần allocation hoặc impact-only semantics','late correction có thể tạo version chứ không overwrite','cancelled event có thuộc grain hay filter phải ghi rõ','unknown member là row có semantics chứ không phải null tuỳ tiện','grain declaration phải được người thứ hai paraphrase cùng nghĩa','profiling phải bao phủ full business cycle','mỗi measure phải kiểm có đúng một value tại grain')), 
Lesson(151,'Lesson_151-conceptual-logical-and-physical-models','Conceptual, logical and physical models','39-conceptual-logical-and-physical-models.md','wiki.data-modeling.model-levels','Làm thế nào tách conceptual, logical và physical model để mỗi artifact trả lời đúng câu hỏi và thay engine không làm nhiễm business semantics?',(M,H,S),(ML,HL,SL),(
('Ba model, ba câu hỏi','Conceptual model hỏi miền có những khái niệm và quan hệ nào; logical model hỏi dữ liệu, identity, cardinality, optionality và constraints biểu diễn ra sao độc lập DBMS; physical model hỏi triển khai trên engine cụ thể bằng types, tables, indexes, partitions, compression và placement nào. Đây là separation of concerns, không phải ba mức trang trí của một diagram.'),
('Conceptual model','Dùng ngôn ngữ nghiệp vụ, bounded context, entity/event/value và quan hệ bậc cao. Không thêm varchar, index hoặc partition. Artifact phục vụ elicitation và alignment nên có thể bỏ chi tiết implementation nhưng không được mơ hồ về thuật ngữ, ownership hay scope. HCMUT system modeling nhấn mạnh mỗi model là một perspective và audience khác nhau.'),
('Logical model','Ghi attributes, candidate identifiers, relationship cardinality/participation, normalization, temporal semantics và integrity constraints. Logical design không đồng nghĩa relational duy nhất; nhưng nếu dùng relational logical model, PK/FK/unique/check ở mức nghĩa chưa cần PostgreSQL syntax. Grain và identity phải ổn định trước physical tuning.'),
('Physical model','Chọn concrete data types, nullability syntax, index access paths, clustering, partitioning, distribution, storage format và engine-specific constraints. Denormalization có thể là physical optimization nếu canonical logical dependencies vẫn rõ. Migration/DDL, capacity và operational controls nằm ở tầng này.'),
('Traceability và change','Mỗi physical object trace về logical element và conceptual term/requirement. Đổi engine chủ yếu tạo physical transformation; nếu business term hoặc cardinality đổi thì đó là requirement/model change, không phải port đơn thuần. Một sơ đồ duy nhất có thể tạo views khác nhau nhưng phải gắn audience/layer, không trộn notation ngầm.'),
),('business term và relationship thuộc conceptual view','candidate key và cardinality thuộc logical view','varchar length và collation thuộc physical view','normalization dependency là logical decision','index và partition là physical access decision','denormalized cache không được làm mất canonical semantics','engine migration không nên đổi business vocabulary','conceptual diagram không nên chứa DBMS type','physical diagram không thay data dictionary','logical nullability phải có business meaning','mỗi layer cần owner và version','traceability phải đi từ requirement tới DDL','một artifact đa-view phải ghi filter/layer rõ','CIM/PIM/PSM là phép tương tự không đồng nhất hoàn toàn với ba data-model levels','boundary decision cần ghi cả hai cách hiểu khi thật sự giao thoa')), 
Lesson(152,'Lesson_152-keys-natural-surrogate-and-identity-over-time','Keys - natural, surrogate and identity over time','40-keys-natural-surrogate-and-identity-over-time.md','wiki.data-modeling.keys-identity-over-time','Natural key, surrogate key và identity resolution phối hợp thế nào khi mã nghiệp vụ đổi, bị tái sử dụng hoặc hai bản ghi phải merge/split?',(K,H,S),(KL,HL,SL),(
('Ba lớp identity','Business/natural key do miền hoặc source cấp; warehouse surrogate key là identifier nội bộ ổn định cho row/version; canonical entity ID nối nhiều source records vào một identity nếu có resolution process. Không một loại nào tự thay thế hai loại còn lại. Source system và effective time thường là một phần của uniqueness scope.'),
('Lý do dùng surrogate','Operational code có thể dài, thay đổi, trùng qua sources hoặc tái sử dụng. Integer surrogate làm fact FK nhỏ và tách lịch sử warehouse khỏi lifecycle source. Kimball dùng surrogate để biểu diễn unknown/not-applicable và SCD versions. Nhưng surrogate chỉ đảm bảo technical uniqueness; vẫn phải lưu business key và constraint/matching rule.'),
('Uniqueness theo thời gian','Mã khách có thể unique tại một thời điểm nhưng tái cấp sau closure. Mô hình cần effective_from/effective_to, source và non-overlap constraint; unique(code) tuyệt đối có thể sai, còn bỏ constraint hoàn toàn cũng sai. Hai intervals cùng code không được overlap nếu contract là temporal uniqueness.'),
('Merge và split','Khi hai source records hóa ra một người, không xóa lịch sử. Ghi mapping/identity link có provenance, effective time và decision version; facts có thể được interpreted theo identity hiện tại hoặc identity known-at-time. Split đảo một merge sai khó hơn và cần immutable lineage. Golden record không đồng nghĩa xoá source identities.'),
('Hash key','Deterministic hash hỗ trợ distributed key generation nhưng cần canonicalization, delimiter/type/null rules, algorithm/version và collision plan. Null/empty/unknown không được trộn. Hash business key vẫn đổi khi business key đổi và không giải quyết entity resolution. Không tuyên bố collision impossible; dùng unique business constraint và kiểm collision.'),
),('natural key phải kèm source namespace khi codes trùng','surrogate key không thay business-key reconciliation','reused code cần temporal non-overlap','SCD version surrogate khác canonical entity identity','merge cần lineage thay vì delete duplicate','split cần đảo mapping theo effective period','hash input phải có canonical null/delimiter/type rules','algorithm version phải được lưu khi hash thay đổi','collision cần detection và resolution','unknown member khác missing source key','late-arriving dimension cần inferred/unknown handling','business key change không nên rewrite fact history tuỳ tiện','PII matching cần privacy/approval boundary','manual identity decision cần reviewer và evidence','crosswalk table phải có uniqueness và temporal tests')), 
Lesson(153,'Lesson_153-dimensional-modelling-facts-dimensions-and-the-bus-matrix','Dimensional modelling - facts, dimensions and the bus matrix','41-dimensional-modeling-facts-dimensions-bus-matrix.md','wiki.data-modeling.facts-dimensions-bus-matrix','Facts, dimensions, conformed dimensions và bus matrix ghép thành kiến trúc dimensional có thể tích hợp nhiều business process như thế nào?',(K,S,D),(KL,SL,DL),(
('Mục tiêu dimensional model','Dimensional model ưu tiên query usability và performance ở presentation layer. Fact table đặt measurements/events ở declared grain cùng dimension foreign keys; dimension chứa descriptive context, labels và hierarchies. Dimension thường rộng/flat có chủ ý. Điều này không phủ nhận normalization cho operational integrity; hai model phục vụ workload khác.'),
('Facts và dimensions','Fact thường numeric nhưng không phải mọi number là fact; postcode/account code là descriptors/identifiers. Fact phải đúng grain và có aggregation semantics. Dimension attribute phải đơn trị tại grain; multivalued relation cần bridge hoặc grain khác. Degenerate dimension là transaction identifier nằm trong fact khi không có thêm attributes.'),
('Conformed dimensions','Dimension conformed có cùng keys, domain values, attribute meanings và governance để lọc/so sánh nhiều fact tables. Hai bảng cùng tên customer nhưng khác definition không conformed. Conformance có thể identical hoặc one là strict subset/rollup có mapping hợp lệ. Owner, change policy và tests quan trọng hơn copy schema.'),
('Bus matrix','Rows là business processes/fact candidates; columns là dimensions; cells cho biết applicability/role. Matrix là planning/governance artifact: phát hiện common dimensions, delivery increments, gaps và conflicting vocabulary. Nó không thay detailed grain/model. Mỗi row cần grain statement; mỗi column cần definition và steward.'),
('Integration boundary','Drill-across kết quả từ fact tables riêng qua conformed dimensions, không join two facts trực tiếp ở detail nếu gây many-to-many explosion. Shared date/product/customer cho consistent filters; measures vẫn giữ riêng. Bus matrix phải version theo domain evolution và ghi role-playing dimensions như order date/ship date.'),
),('fact measure phải đúng declared grain','numeric identifier không tự thành measure','dimension attribute phải đơn trị tại fact grain','multivalued dimension cần bridge semantics','degenerate dimension không phải fact','conformed dimension cần semantic chứ không chỉ column-name equality','bus matrix row là process không department','bus matrix cell không thay grain definition','role-playing dates dùng một conformed dimension với roles','fact-to-fact detail join dễ tạo many-to-many explosion','drill-across aggregate theo shared dimensions','dimension denormalization là intentional presentation choice','unknown members cần conformed handling','slowly changing policy phải nhất quán qua facts','matrix cần owner/version/change review')), 
Lesson(154,'Lesson_154-fact-types-transaction-periodic-and-accumulating-snapshot','Fact types - transaction, periodic and accumulating snapshot','42-fact-types-transaction-periodic-accumulating.md','wiki.data-modeling.fact-table-types','Transaction, periodic snapshot và accumulating snapshot khác nhau ở grain, load rhythm, update semantics và câu hỏi nghiệp vụ nào?',(K,S,D),(KL,SL,DL),(
('Transaction fact','Một row cho event ở thời điểm xảy ra; thường insert-only sau khi posted. Nó trả lời chuyện gì xảy ra, ở đâu, với ai và bao nhiêu. Grain phải là event detail thấp nhất hữu dụng. Không có row nghĩa là event không xảy ra hoặc chưa được capture; không suy state tại một ngày chỉ từ event nếu business logic phức tạp.'),
('Periodic snapshot','Một row cho entity/cohort tại end-of-period đều đặn, kể cả kỳ có thể không có event theo design. Phù hợp balances, inventory và trendable status. Load là insert per period; prior periods giữ lại. Snapshot có thể chứa semi-additive measures nên time aggregation phải dùng ending/average/min/max theo contract.'),
('Accumulating snapshot','Một row theo pipeline instance, có nhiều milestone dates và được revisit/update khi lifecycle tiến triển. Hợp với process hữu hạn, predictable stages như order fulfillment/claim. Grain không phải mỗi milestone; là một pipeline instance ở lowest tracked detail. Long-lived/open-ended process có thể không phù hợp.'),
('Idempotency và backfill','Transaction load dedupe theo event identity; periodic snapshot replace/merge một entity-period; accumulating snapshot upsert deterministic milestone state. Backfill phải cho cùng output với sequential run ở cùng cutoff. Late event có thể sửa milestone và derived lags; audit update/source watermark để phân biệt replay với business correction.'),
('Complementary models','Một domain thường cần cả event fact và snapshot fact. Transaction giữ chi tiết/audit; periodic cho state trend; accumulating cho cycle time. Redundancy có chủ ý nhưng reconciliation phải định nghĩa source-of-truth và equations. Factless fact table ghi occurrence/coverage/relationship để đếm khi không có numeric measure.'),
),('transaction fact có grain một event occurrence','periodic snapshot cần explicit period/cutoff/timezone','accumulating snapshot update existing pipeline row','nhiều date columns không tự chứng minh accumulating snapshot','balance không suy đơn giản từ transaction khi business rules phức tạp','periodic snapshot có thể cần dense rows cho zero/no-activity','late event có thể sửa prior snapshot theo restatement policy','backfill phải idempotent và cutoff-aware','transaction dedupe cần stable event identity','accumulating milestone update cần monotonicity hoặc correction rule','cycle time tính từ milestone timestamps và null handling','factless fact ghi occurrence hoặc coverage','companion fact tables cần reconciliation equation','snapshot retention khác raw event retention','chọn loại theo question chứ theo table-name convention')), 
Lesson(155,'Lesson_155-additivity-additive-semi-additive-and-non-additive-measures','Additivity - additive, semi-additive and non-additive measures','43-additivity-additive-semi-additive-non-additive.md','wiki.data-modeling.measure-additivity','Một measure được phép aggregate bằng toán tử nào trên dimension nào, và thiết kế numerator/denominator hay distinct-state nào tránh số đúng cú pháp nhưng sai nghĩa?',(K,S,D),(KL,SL,DL),(
('Additivity là contract theo chiều','Measure không chỉ có type; cần aggregation contract cho từng dimension. Additive measure như transaction amount có thể SUM qua các dimensions nếu currency/unit cùng semantics. Additivity phụ thuộc grain, unit và filter; revenue nhiều currency không cộng trực tiếp dù mỗi row numeric.'),
('Semi-additive','Balance và inventory thường cộng qua customer/product/location nhưng không qua time. SUM daily balances trả area-under-curve chứ không phải ending balance. Chọn last non-empty, end-of-period, average theo time-weighting, min/max hoặc exposure integral tùy câu hỏi. Ghi snapshot cadence và missing-period policy.'),
('Non-additive ratios','Rate, percentage và average không SUM. Average of averages sai khi denominators khác; lưu numerator và denominator additive components, aggregate chúng rồi divide ở cuối. Weighted average cần explicit weight. Division-by-zero/null policy và unit phải quản trị ở semantic layer, không để mỗi dashboard tự chọn.'),
('Distinct count','Distinct customers không cộng qua partitions/time vì cùng entity xuất hiện nhiều nhóm. Exact aggregate cần union underlying identifiers hoặc recompute ở query grain; sketches như HLL merge được nhưng approximate và có error/version contract. Precomputed distinct counts chỉ cộng khi sets proven disjoint.'),
('Kiểm bằng phản ví dụ','Tạo dataset nhỏ với denominators lệch, repeated customer và daily balances. So wrong aggregation với ground truth từ atomic rows; định lượng absolute/relative error. Metric catalog ghi grain, expression, allowed dimensions/operators, filters, currency/timezone, null and late-data policy. Test rollup ở nhiều levels và invariant numerator≤denominator khi phù hợp.'),
),('revenue chỉ additive khi currency/unit đã đồng nhất','balance semi-additive theo time','inventory snapshot SUM qua days không ra stock cuối kỳ','average of averages sai khi group sizes khác','ratio phải aggregate numerator và denominator trước division','weighted average cần explicit weight','percent không được SUM','distinct count không cộng qua overlapping sets','HLL mergeable nhưng approximate/error-versioned','last non-empty cần cutoff và missing semantics','flow measure khác stock measure','unit conversion factor có effective time','null khác zero trong metric contract','late data có thể restate denominator và historical rate','semantic tests phải chạy ở nhiều rollup levels')),
)

def fm(x):
 src='\n'.join(f'  - {s}' for s in x.sources)
 return f'''---
note_id: {x.note_id}
note_type: concept-deep-dive
status: review
language: vi
created: 2026-10-01
last_verified: 2026-10-01
editorial_pass: humanized-v1
primary_question: {x.question}
source_ids:
{src}
aliases: [{x.title}]
tags: [wiki/database-systems, data-modeling, module-11]
reference_path: Material/DE/Reference/Library/Knowledge-Notes/PACK-DATABASE-MODELING-BOOK-01/{x.filename}
---
'''

VERIFY={
150:'Dựng fixture chứa trường hợp thường, split, return, correction và duplicate. Viết grain thành một câu, suy ra candidate business key, rồi đối chiếu row count, duplicate groups, null rate và control total trước–sau join. Kết quả đạt phải chỉ ra được phản ví dụ nào bác bỏ grain; không dùng việc không thấy duplicate trong sample để tuyên bố grain đúng.',
151:'Lập ba artifact tách biệt: glossary/concept map, logical model và DDL/index plan. Lập ma trận trace từ requirement đến term, entity/constraint và physical object. Sau đó thay DBMS hoặc access pattern: thay đổi chỉ được lan sang physical layer nếu business semantics không đổi. Bằng chứng đạt là diff theo layer và mọi object đều truy ngược được.',
152:'Tạo identity timeline có code change, code reuse, hai source trùng mã, merge và split. Kiểm business uniqueness theo namespace/effective time, non-overlap, surrogate uniqueness và crosswalk lineage bằng truy vấn tái chạy. Bằng chứng đạt phải giữ được source identity, warehouse version và canonical identity mà không rewrite lịch sử.',
153:'Chọn hai business process dùng chung customer, product và date. Viết grain cho từng fact, data dictionary cho dimensions, rồi lập bus matrix và truy vấn drill-across. Đối chứng bằng direct fact-to-fact detail join. Bằng chứng đạt gồm row counts, control totals và chứng minh shared dimension thật sự cùng key/domain/meaning, không chỉ cùng tên cột.',
154:'Phát cùng một event stream vào ba thiết kế: transaction, periodic snapshot và accumulating snapshot. Chạy normal load, replay, late event và backfill tại cùng cutoff. Bằng chứng đạt là grain/key không bị nhân, state/milestone được reconcile với event ledger và rerun tạo cùng output theo policy restatement đã ghi.',
155:'Tạo bộ dữ liệu nhỏ có denominator lệch, khách hàng lặp qua nhóm, balance theo ngày, nhiều currency và missing period. Tính ground truth từ atomic rows, sau đó so SUM, average-of-averages, distinct-count cộng dồn và last-non-empty. Bằng chứng đạt ghi rõ operator hợp lệ theo từng dimension, unit/cutoff/null policy và sai số của phép tính sai.',
}

def deep_note(x):
 parts=[fm(x),f'# {x.title}\n\n> [!abstract] Câu hỏi trung tâm\n> {x.question}\n']
 for i,(h,b) in enumerate(x.core,1): parts.append(f'\n## {i}. {h}\n\n{b}\n')
 parts.append('\n## 6. Ma trận kiểm chứng từng mệnh đề\n\nMỗi mệnh đề phải được chuyển thành invariant, fixture và phép đối chiếu có thể chạy lại. Sơ đồ đẹp hoặc một truy vấn trả về kết quả không lỗi không tự chứng minh mô hình đúng ngữ nghĩa.\n')
 for i,p in enumerate(x.probes,1):
  parts.append(f'\n### 6.{i}. {p}\n\n**Mệnh đề cần kiểm.** {p}. **Thiết kế phép kiểm.** {VERIFY[x.number]} **Hồ sơ cần lưu.** Grain/model/metric contract, dữ liệu seed, SQL hoặc notebook, kết quả thô, control totals và giải thích ca biên. Nếu phép kiểm chỉ xác nhận cấu trúc mà không xác nhận semantics, kết luận phải ghi rõ giới hạn đó.\n')
